def level_check(self):
    """Checks whether we should level up or down."""
    # Add consumption of construction material
    self.consume_construction_material()
    if self.happiness > SETTLER.HAPPINESS_LEVEL_UP_REQUIREMENT:
        self.level_up()
        self._changed()
    elif self.happiness < SETTLER.HAPPINESS_LEVEL_DOWN_LIMIT:
        self.level_down()
        self._changed()
